// backend/src/core/ai/tasks/tasks.types.ts
export interface TaskStep {
  stepNumber: number;
  action: string;
  result: string;
  requiresApproval: boolean;
  approvalToken?: string;
  timestamp: string;
}

export interface Task {
  taskId: string;
  userId: string;
  tenantId: string;
  goal: string;
  maxSteps: number;
  currentStep: number;
  status: 'pending' | 'running' | 'waiting_approval' | 'completed' | 'failed' | 'cancelled';
  history: TaskStep[];
  createdAt: string;
  updatedAt: string;
}

export interface StartTaskRequest {
  goal: string;
  maxSteps?: number;
}

export interface StartTaskResponse {
  taskId: string;
  status: string;
}

export interface StepTaskResponse {
  stepResult: string;
  status: string;
  currentStep: number;
  maxSteps: number;
  waitingApproval?: {
    token: string;
    action: string;
  };
}















